from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)

        prefix_nums = [0] * (n + 1)
        prefix_cost = [0] * (n + 1)

        for i in range(n):
            prefix_nums[i + 1] = prefix_nums[i] + nums[i]
            prefix_cost[i + 1] = prefix_cost[i] + cost[i]

        total_cost = prefix_cost[n]
        dp = [float("inf")] * (n + 1)
        dp[0] = 0

        for r in range(1, n + 1):
            for l in range(r):
                dp[r] = min(
                    dp[r],
                    dp[l]
                    + prefix_nums[r] * (prefix_cost[r] - prefix_cost[l])
                    + k * (total_cost - prefix_cost[l])
                )

        return dp[n]
